<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { Bell, Connection, DataAnalysis, Monitor, Operation, Refresh, SetUp } from '@element-plus/icons-vue'
import { appDefinitions } from '../utils/apps'

const router = useRouter()
const selectedKey = ref('')
const capabilityMap = {
  console: { icon: Monitor, tone: 'blue', role: '统一入口', description: '提供统一工作台、系统配置、用户权限与操作审计入口。', capabilities: ['仪表盘与全局视图', '业务拓扑图', '用户与权限管理', '组织与菜单配置', '登录与操作审计'], consumers: ['assets', 'ops', 'applications', 'notify', 'integration', 'monitor'] },
  assets: { icon: SetUp, tone: 'cyan', role: '资源底座', description: '统一管理主机、云账号、数据库、网关、K8s 与服务运行资源。', capabilities: ['资产概览', '主机与凭据管理', '云账号与云主机同步', '数据库管理', '网关管理', 'K8s 管理', '服务管理', '终端登录'], consumers: ['ops', 'applications', 'integration', 'monitor'] },
  ops: { icon: Operation, tone: 'violet', role: '运维执行', description: '基于资产与环境执行脚本、命令、文件分发、作业和定时任务。', capabilities: ['环境模型', '脚本库', '快速执行', '文件分发', '定时任务', '作业编排', '人工确认', '执行历史与模板'], consumers: ['applications'] },
  applications: { icon: Connection, tone: 'green', role: '应用交付', description: '管理应用项目、构建发布流水线、应用环境绑定和资源拓扑。', capabilities: ['项目列表', '应用拓扑', '构建任务', '构建历史', 'CI/CD 流水线'], consumers: ['monitor'] },
  monitor: { icon: DataAnalysis, tone: 'orange', role: '可观测性', description: '采集并查询指标、日志与告警，形成仪表盘、告警规则和事件闭环。', capabilities: ['监控概览与仪表盘', '监控数据源', '指标查询', '日志查询', '告警规则', '告警事件与处置', '告警治理与巡检'], consumers: ['notify', 'integration'] },
  notify: { icon: Bell, tone: 'pink', role: '消息触达', description: '通过模板、渠道和通知规则将告警或运维结果触达相关人员。', capabilities: ['通知规则', '消息模板', '通知媒介', '发送日志'], consumers: ['console'] },
  integration: { icon: Connection, tone: 'indigo', role: '外部集成与智能分析', description: '提供 AI 助手、模型与工具集，并完成云费用分析、账单同步与优化建议。', capabilities: ['导航管理', 'AI 助手与会话', '模型与工具集', '云费用看板', '账单同步与费用拆分', '优化建议与资源分析'], consumers: ['console'] }
}
const nodes = computed(() => appDefinitions.filter(item => capabilityMap[item.key]).map(item => ({ ...item, ...capabilityMap[item.key] })))
const selectedNode = computed(() => nodes.value.find(item => item.key === selectedKey.value) || null)
const capabilityCount = computed(() => nodes.value.reduce((total, item) => total + item.capabilities.length, 0))
const edges = computed(() => nodes.value.flatMap(item => item.consumers.map(target => ({ source: item.key, target }))))
function openApp(node) { router.push(node.defaultRoute) }
function selectNode(key) { selectedKey.value = selectedKey.value === key ? '' : key }
</script>

<template>
  <div class="business-topology-page">
    <section class="topology-hero"><div><p>OPS ADMIN · BUSINESS TOPOLOGY</p><h1>业务拓扑图</h1><span>以“应用 → 多项业务能力”的方式展示当前平台全部应用。</span></div><div class="hero-meta"><strong>{{ nodes.length }}</strong><span>个业务应用</span><strong>{{ capabilityCount }}</strong><span>项实现能力</span></div></section>
    <section class="legend-bar"><span><i class="dot resource"></i>资源与数据</span><span><i class="dot execution"></i>运维与交付</span><span><i class="dot observe"></i>监控与告警</span><span><i class="dot output"></i>通知与智能分析</span><em>点击父节点或能力卡片可查看详细职责。</em></section>
    <section class="topology-canvas"><header><strong>7 个应用</strong><b>→</b><strong>{{ capabilityCount }} 项业务能力</strong><span>每一列代表一个应用及其实现功能</span></header><div class="capability-lanes"><article v-for="node in nodes" :key="node.key" class="capability-lane" :class="[`tone-${node.tone}`, { selected: selectedKey === node.key }]"><button class="application-parent" @click="selectNode(node.key)" @dblclick="openApp(node)"><i class="app-icon"><el-icon><component :is="node.icon" /></el-icon></i><span><small>{{ node.role }}</small><b>{{ node.name }}</b></span><em title="进入应用" @click.stop="openApp(node)">↗</em></button><div class="stem"></div><button v-for="capability in node.capabilities" :key="capability" class="capability-node" @click="selectNode(node.key)">{{ capability }}</button></article></div><div class="relation-list"><span v-for="edge in edges" :key="`${edge.source}-${edge.target}`">{{ nodes.find(item => item.key === edge.source)?.name }} <b>→</b> {{ nodes.find(item => item.key === edge.target)?.name }}</span></div></section>
    <section class="capability-section"><div class="section-heading"><div><p>APPLICATION CAPABILITIES</p><h2>{{ selectedNode ? selectedNode.name : '应用功能说明' }}</h2></div><el-button :icon="Refresh" @click="selectedKey = ''">清除选择</el-button></div><div v-if="selectedNode" class="capability-detail" :class="`tone-${selectedNode.tone}`"><div><span>应用定位</span><strong>{{ selectedNode.role }}</strong><p>{{ selectedNode.description }}</p></div><div><span>实现功能</span><ul><li v-for="item in selectedNode.capabilities" :key="item">{{ item }}</li></ul></div><div><span>业务输出给</span><ul><li v-for="key in selectedNode.consumers" :key="key">{{ nodes.find(item => item.key === key)?.name }}</li></ul></div></div><div v-else class="capability-grid"><article v-for="node in nodes" :key="node.key" :class="`tone-${node.tone}`" @click="selectNode(node.key)"><strong>{{ node.name }}</strong><p>{{ node.description }}</p></article></div></section>
    <section class="topology-note"><el-icon><Connection /></el-icon><div><strong>链路说明</strong><p>上方突出“七对多”能力关系；底部标签补充应用间真实的数据和业务输出方向，例如资产管理向监控中心提供运行对象，监控中心向消息通知输出告警事件。</p></div></section>
  </div>
</template>

