e-pink .app-icon,.tone-pink .capability-node:before{background:#ed668c}.tone-indigo .application-parent{border-top-color:#5268d9}.tone-indigo .app-icon,.tone-indigo .capability-node:before{background:#5268d9}.capability-section{padding:20px;border:1px solid #e0e9f6;border-radius:16px;background:#fff}.section-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}.section-heading h2{margin:5px 0 0;color:#17345d;font-size:20px}.section-heading p{color:#6c85b0}.capability-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.capability-grid article{padding:14px;border:1px solid #e1e9f5;border-left:4px solid #5f7cf0;border-radius:10px;cursor:pointer}.capability-grid article:hover{background:#f7f9ff}.capability-grid article p{margin:8px 0 0;color:#71849e;font-size:12px;line-height:1.55}.capability-detail{display:grid;grid-template-columns:1.15fr 1fr 1fr;gap:18px;padding:18px;border:1px solid #e1e9f5;border-left:5px solid #5f7cf0;border-radius:12px;background:#fbfcff}.capability-detail span{display:block;color:#7689a6;font-size:12px}.capability-detail strong{display:block;margin:7px 0;color:#17345d;font-size:18px}.capability-detail p,.capability-detail ul{margin:7px 0 0;color:#627896;font-size:13px;line-height:1.7}.capability-detail ul{padding-left:18px}.topology-note{align-items:flex-start}.topology-note strong{color:#294361}.topology-note p{margin:4px 0 0;font-size:13px;line-height:1.6}@media(max-width:1100px){.capability-lanes{grid-template-columns:repeat(3,minmax(180px,1fr));overflow:visible}.capability-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:680px){.topology-hero{align-items:flex-start;flex-direction:column}.capability-lanes,.capability-grid,.capability-detail{grid-template-columns:1fr}.topology-canvas>header{align-items:flex-start;flex-wrap:wrap}.topology-canvas>header span{width:100%;margin-left:0}.legend-bar{align-items:flex-start;flex-wrap:wrap}.legend-bar em{margin-left:0}.hero-me